// Stub for the Google Calendar node. Change CASE, execute, read the result.
const CASE = 'A';

const ev = (start, end, summary) => ({
  json: {
    status: 'confirmed',
    summary,
    start: { dateTime: `2026-08-05T${start}:00+07:00` },
    end:   { dateTime: `2026-08-05T${end}:00+07:00` },
  },
});

const CASES = {
  // A: empty calendar. One field-less item, not zero items - see note below.
  A: [{ json: {} }],

  // B: four treatments running straight through 14:00-15:30. Capacity full.
  B: [
    ev('14:00', '15:30', 'B1'),
    ev('14:00', '15:30', 'B2'),
    ev('14:00', '15:30', 'B3'),
    ev('14:00', '15:30', 'B4'),
  ],

  // C: FIVE events all touching the candidate window, but never more than
  // THREE at once. Counting events says busy; counting concurrency says free.
  C: [
    ev('13:00', '14:00', 'C1'),
    ev('13:15', '14:00', 'C2'),
    ev('14:45', '15:30', 'C3'),
    ev('15:00', '15:30', 'C4'),
    ev('14:30', '15:00', 'C5'),
  ],

  // D: all-day entry. Meaning is ambiguous, must escalate.
  D: [{ json: { status: 'confirmed', summary: 'D1', start: { date: '2026-08-05' }, end: { date: '2026-08-06' } } }],
};

return CASES[CASE];

// Availability check. Runs after the calendar events node.
// Emits ONE item; a Switch downstream routes on json.decision.
// WHY the calendar and not the bookings table: the front desk adds walk-ins
// and phone bookings straight to the calendar. A DB-only check cannot see
// those and will double-book.

// ── CONFIG ────────────────────────────────────────────────────────────
const TZ = 'Asia/Bangkok';
const CAPACITY = 4;         // therapists. The binding constraint; rooms are not.
const TURNOVER_MIN = 15;
const OPEN_HOUR = 10;
const CLOSE_HOUR = 20;
const SLOT_GRID_MIN = 30;
const MIN_LEAD_MIN = 60;    // PLACEHOLDER - no same-minute bookings
const MAX_OFFERS = 4;       // keep the reply email readable

// PLACEHOLDER durations in minutes. Keys must stay identical to the
// treatment enum in the classifier schema.
const DURATIONS = {
  treatment_a: 60,
  treatment_b: 60,
  treatment_c: 90,
  treatment_d: 90,
  treatment_e: 120,
  treatment_f: 120,
};

// ── HELPERS ───────────────────────────────────────────────────────────

// Max simultaneously-busy therapists over [from, to). Sweep line.
// NOT a count of overlapping events: five events can touch a 90-minute
// window while never more than two run at once. Counting events instead of
// concurrency rejects bookable slots.
function maxConcurrent(busy, from, to) {
  const points = [];
  for (const b of busy) {
    const s = b.start < from ? from : b.start;
    const e = b.end > to ? to : b.end;
    if (e <= s) continue;
    points.push([s.toMillis(), 1]);
    points.push([e.toMillis(), -1]);
  }
  // At an identical instant, close before open, so back-to-back events
  // do not read as overlapping.
  points.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  let current = 0;
  let peak = 0;
  for (const [, delta] of points) {
    current += delta;
    if (current > peak) peak = current;
  }
  return peak;
}

function parseEvents(items) {
  const busy = [];
  let hasAllDay = false;

  for (const item of items) {
    const e = item.json || {};
    if (e.status === 'cancelled') continue;
    if (e.transparency === 'transparent') continue;

    // All-day entries carry start.date, not start.dateTime. A therapist's
    // day off is capacity 3, a public holiday is capacity 0. Do not guess.
    if (e.start && e.start.date && !e.start.dateTime) {
      hasAllDay = true;
      continue;
    }
    if (!e.start || !e.start.dateTime || !e.end || !e.end.dateTime) continue;

    busy.push({
      start: DateTime.fromISO(e.start.dateTime, { zone: TZ }),
      // Turnover belongs to the therapist, so it extends the busy interval.
      end: DateTime.fromISO(e.end.dateTime, { zone: TZ })
        .plus({ minutes: TURNOVER_MIN }),
    });
  }
  return { busy, hasAllDay };
}

// Bookable if the treatment finishes by closing time AND a therapist is
// free for every instant it occupies.
function isBookable(start, durationMin, busy) {
  const treatmentEnd = start.plus({ minutes: durationMin });
  const close = start.set({ hour: CLOSE_HOUR, minute: 0, second: 0, millisecond: 0 });
  if (treatmentEnd > close) return false;

  const blockEnd = treatmentEnd.plus({ minutes: TURNOVER_MIN });
  return maxConcurrent(busy, start, blockEnd) < CAPACITY;
}

function openSlots(day, durationMin, busy, now) {
  const out = [];
  const earliest = now.plus({ minutes: MIN_LEAD_MIN });
  let cursor = day.set({ hour: OPEN_HOUR, minute: 0, second: 0, millisecond: 0 });
  const close = day.set({ hour: CLOSE_HOUR, minute: 0, second: 0, millisecond: 0 });

  while (cursor.plus({ minutes: durationMin }) <= close) {
    if (cursor >= earliest && isBookable(cursor, durationMin, busy)) {
      out.push(cursor);
    }
    cursor = cursor.plus({ minutes: SLOT_GRID_MIN });
  }
  return out;
}

const fmtTime = (dt) => dt.toFormat('HH:mm');
const fmtDate = (dt) => dt.toFormat('cccc d LLLL');

// ── MAIN ──────────────────────────────────────────────────────────────

const req = $('Classify Intent').first().json;
const now = DateTime.now().setZone(TZ);
const parsed = parseEvents($input.all());
const busy = parsed.busy;
const hasAllDay = parsed.hasAllDay;

const out = (decision, extra) => [{
  json: Object.assign(
    { decision: decision, treatment: req.treatment || null },
    extra || {}
  ),
}];

// Rule 4 of the classifier makes these mutually exclusive, so both being set
// is impossible by construction. If it happens the model output is not what
// it appears to be, and acting on it is unsafe.
if (req.requested_start && req.requested_date) {
  return out('escalate', { reason: 'impossible_flag_combination' });
}

const durationMin = DURATIONS[req.treatment];
if (!durationMin) {
  return out('escalate', { reason: 'unknown_treatment' });
}

// Ambiguous calendar entry in the window. Default when unsure is ASK.
if (hasAllDay) {
  return out('escalate', { reason: 'all_day_event_in_window' });
}

// ── exact time requested ──
if (req.requested_start) {
  const start = DateTime.fromISO(req.requested_start, { zone: TZ });
  if (!start.isValid) {
    return out('escalate', { reason: 'unparseable_start' });
  }

  if (isBookable(start, durationMin, busy)) {
    const treatmentEnd = start.plus({ minutes: durationMin });
    return out('slot_available', {
      start_iso: start.toISO(),
      end_iso: treatmentEnd.toISO(),
      start_human: fmtDate(start) + ' at ' + fmtTime(start),
      duration_min: durationMin,
    });
  }

  // Busy: offer nearest same-day alternatives rather than a bare no.
  const alternatives = openSlots(start.startOf('day'), durationMin, busy, now)
    .sort((a, b) =>
      Math.abs(a.diff(start).toMillis()) - Math.abs(b.diff(start).toMillis()))
    .slice(0, MAX_OFFERS)
    .sort((a, b) => a.toMillis() - b.toMillis());

  return out(alternatives.length ? 'slot_busy' : 'day_full', {
    requested_human: fmtDate(start) + ' at ' + fmtTime(start),
    date_human: fmtDate(start),
    duration_min: durationMin,
    offers: alternatives.map((s) => ({ iso: s.toISO(), human: fmtTime(s) })),
  });
}

// ── date only, no clock time ──
if (req.requested_date) {
  const day = DateTime.fromISO(req.requested_date, { zone: TZ });
  if (!day.isValid) {
    return out('escalate', { reason: 'unparseable_date' });
  }

  const slots = openSlots(day.startOf('day'), durationMin, busy, now)
    .slice(0, MAX_OFFERS);

  return out(slots.length ? 'day_slots' : 'day_full', {
    date_human: fmtDate(day),
    duration_min: durationMin,
    offers: slots.map((s) => ({ iso: s.toISO(), human: fmtTime(s) })),
  });
}

// The router upstream should have caught this. Fail to ASK, not to ACT.
return out('escalate', { reason: 'no_date_supplied' });

const booking = $input.first().json;          // {id, booking_ref}
const slot = $('Route Decision').first().json;
const req = $('Classify Intent').first().json;

const ref = booking.booking_ref;
const name = req.client_name || 'there';

// The ref must survive being quoted in a reply: the cancel/reschedule path
// regex-extracts it from the FULL body, quoted text included. Keep it on its
// own line, unstyled, no markup that could split the token.
const body = [
  `Hi ${name},`,
  ``,
  `Your booking is confirmed.`,
  ``,
  `  ${slot.start_human}`,
  `  ${slot.treatment} (${slot.duration_min} minutes)`,
  ``,
  `Booking reference: ${ref}`,
  ``,
  `To change or cancel, just reply to this email and quote your booking`,
  `reference above. Please give us at least 24 hours' notice.`,
  ``,
  `Payment is on arrival.`,
  ``,
  `See you soon,`,
  `Chiang Mai Wellness Retreat`,
].join('\n');

return [{
  json: {
    booking_ref: ref,
    to: req.client_email || 'nan@example.com',
    subject: `Booking confirmed — ${slot.start_human} (${ref})`,
    body: body,
  },
}];

const requested = DateTime.fromISO($('Route Decision').first().json.start_iso);
const found = $input.first().json.bookings || [];

// The API returns starts_at in UTC with a space separator
// ("2026-08-05 07:00:00+00:00"); the request carries +07:00. Same instant,
// different text - compare instants, never strings, or this guard silently
// never matches and looks like it is working.
const parse = (s) => DateTime.fromISO(String(s).replace(' ', 'T'));

const dup = found.find(
  (b) => parse(b.starts_at).toMillis() === requested.toMillis()
);

return [{
  json: {
    is_duplicate: Boolean(dup),
    existing_ref: dup ? dup.booking_ref : null,
    checked_count: found.length,
  },
}];
